(()=>{const root=document.getElementById('M05-lab');if(!root)return;const zh=document.documentElement.lang.startsWith('zh');const pts=[[-2,-1,-1],[-2,1,-1],[-1,0,-1],[1,0,1],[2,-1,1],[2,1,1],[-.8,.3,1]],defaults={angle:0,norm:1,bias:0,C:1};let p={...defaults},s={};const el=k=>document.getElementById('M05-'+k),sx=x=>80+(x+3)*80,sy=y=>380-(y+2)*80;
function render(){const a=p.angle*Math.PI/180,w=[p.norm*Math.cos(a),p.norm*Math.sin(a)],m=pts.map(t=>t[2]*(w[0]*t[0]+w[1]*t[1]+p.bias)),h=m.map(v=>Math.max(0,1-v)),hinge=h.reduce((a,b)=>a+b,0);s={...p,hinge,objective:.5*p.norm*p.norm+p.C*hinge,violations:h.filter(x=>x>1e-8).length,errors:m.filter(x=>x<=0).length,width:2/p.norm};let svg='<rect x="80" y="60" width="480" height="320" fill="#f3f7f8"/>';for(let x=-3;x<=3;x++)svg+=`<path d="M${sx(x)} 60V380" stroke="#dbe4e7"/><text x="${sx(x)}" y="402" text-anchor="middle" font-size="14">${x}</text>`;for(let y=-2;y<=2;y++)svg+=`<path d="M80 ${sy(y)}H560" stroke="#dbe4e7"/><text x="65" y="${sy(y)+5}" text-anchor="end" font-size="14">${y}</text>`;for(const v of[-1,0,1]){let edges=[];for(const x of[-3,3])if(Math.abs(w[1])>1e-8){let y=(v-p.bias-w[0]*x)/w[1];if(y>=-2&&y<=2)edges.push([x,y]);}for(const y of[-2,2])if(Math.abs(w[0])>1e-8){let x=(v-p.bias-w[1]*y)/w[0];if(x>=-3&&x<=3)edges.push([x,y]);}if(edges.length>=2)svg+=`<path d="M${sx(edges[0][0])} ${sy(edges[0][1])}L${sx(edges[1][0])} ${sy(edges[1][1])}" stroke="#25424e" stroke-width="${v===0?3:1.5}" ${v?'stroke-dasharray="7 5"':''}/>`;}
pts.forEach((t,i)=>{if(h[i]>1e-8)svg+=`<circle cx="${sx(t[0])}" cy="${sy(t[1])}" r="13" fill="none" stroke="#253e48"/>`;svg+=`<circle cx="${sx(t[0])}" cy="${sy(t[1])}" r="7" fill="${t[2]>0?'#d18544':'#167e88'}"/><text x="${sx(t[0])+15}" y="${sy(t[1])-12}" font-size="13">${i+1}</text>`;});svg+=`<text x="320" y="430" text-anchor="middle" font-size="15">x₁</text><text x="35" y="220" font-size="15">x₂</text><text x="645" y="95" fill="#d18544" font-size="16">+1</text><text x="645" y="125" fill="#167e88" font-size="16">−1</text><text x="645" y="180" font-size="14">${zh?'权重代价':'Weight cost'}</text><text x="645" y="207" font-size="22">${(.5*p.norm*p.norm).toFixed(3)}</text><text x="645" y="260" font-size="14">${zh?'违反代价':'Violation cost'}</text><text x="645" y="287" font-size="22">${(p.C*hinge).toFixed(3)}</text>`;el('plot').innerHTML=svg;el('result').textContent=zh?`铰链损失之和 ${hinge.toFixed(3)}；目标 ${s.objective.toFixed(3)}；违反间隔 ${s.violations} 点；错误 ${s.errors} 点；走廊宽度 ${s.width.toFixed(3)}。`:`Hinge sum ${hinge.toFixed(3)}; objective ${s.objective.toFixed(3)}; ${s.violations} margin violations; ${s.errors} errors; corridor width ${s.width.toFixed(3)}.`;for(const k in p){el(k).value=p[k];el(k+'-value').value=p[k];}}
function set(q){for(const k in defaults)if(q[k]!=null&&Number.isFinite(+q[k])){const e=el(k);p[k]=Math.max(+e.min,Math.min(+e.max,+q[k]));}render();return{...s};}for(const k in defaults)el(k).addEventListener('input',()=>set({[k]:el(k).value}));el('reset').addEventListener('click',()=>{p={...defaults};render();});window.CourseLab={set,state:()=>({...s}),reset:()=>{p={...defaults};render();return{...s};}};render();})();
